import { PASSWORD, USERS, expect, test } from "../../fixtures";

test.describe("sign out", () => {
  test(
    "signing out clears the session cookie",
    { tag: "@AUTH-06" },
    async ({ request }) => {
      // Arrange: sign in so the session cookie is set on the request context.
      const login = await request.post("/api/auth/login", {
        data: { email: USERS.member, password: PASSWORD },
      });
      expect(login.status()).toBe(200);
      const loginCookie = login
        .headersArray()
        .find((h) => h.name.toLowerCase() === "set-cookie");
      expect(loginCookie?.value).toMatch(/^session=/);

      // Act
      const response = await request.post("/api/auth/logout");

      // Assert: status is 204.
      expect(response.status()).toBe(204);

      // Assert: the session cookie is cleared (empty value and expired/zero max-age).
      const clearCookie = response
        .headersArray()
        .find((h) => h.name.toLowerCase() === "set-cookie" && /^session=/i.test(h.value));
      expect(clearCookie, "logout should send a Set-Cookie for session").toBeDefined();
      const cookie = clearCookie!.value;
      expect(cookie).toMatch(/^session=(""|;|$)/);
      const lower = cookie.toLowerCase();
      const expiredByDate = lower.includes("expires=thu, 01 jan 1970");
      const expiredByAge = /max-age=0(;|$)/.test(lower);
      expect(expiredByDate || expiredByAge, `session cookie not expired: ${cookie}`).toBe(true);
    },
  );
});
